<?php
require 'config.php';require_login();$uid=(int)$_SESSION['user_id'];$filter=input_string('action',$_GET);$args=[$uid];$sql='SELECT h.*,t.title FROM task_history h JOIN tasks t ON t.task_id=h.task_id WHERE h.user_id=?';
if(in_array($filter,['CREATED','UPDATED','COMPLETED','POSTPONED','STATUS_CHANGED'],true)){$sql.=' AND h.action_type=?';$args[]=$filter;}
$sql.=' ORDER BY h.action_at DESC,h.history_id DESC LIMIT 100';$q=$pdo->prepare($sql);$q->execute($args);$rows=$q->fetchAll();$pageTitle='Activity history';include 'includes/header.php';?>
<main id="main-content" class="container"><div class="page-heading"><div><p class="eyebrow">EVERY SMALL STEP COUNTS</p><h1>Activity history</h1><p class="muted">A clear record of your task decisions and progress.</p></div><a class="btn secondary" href="analytics.php">View insights <?=icon('arrow-right')?></a></div><section class="panel"><form class="filters" method="get"><div><label for="action">Activity type</label><select id="action" name="action"><option value="">All activity</option><?php foreach(['CREATED','UPDATED','COMPLETED','POSTPONED','STATUS_CHANGED'] as $value):?><option value="<?=$value?>" <?=$value===$filter?'selected':''?>><?=e(status_label($value))?></option><?php endforeach;?></select></div><button class="btn secondary">Filter activity</button></form><p class="field-help">Most recent 100 events. Permanently deleting a task also removes its task history.</p>
<?php if(!$rows):?><div class="empty"><div class="empty-icon"><?=icon('history')?></div><h2>Your progress starts with one task.</h2><p>Create or update a task to start building your activity timeline.</p><a class="btn primary" href="add_task.php">Create a task</a></div><?php else:?><div class="table-wrap"><table><thead><tr><th scope="col">Task</th><th scope="col">Activity</th><th scope="col">Details</th><th scope="col">When</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><strong><?=e($row['title'])?></strong></td><td><span class="pill"><?=e(status_label($row['action_type']))?></span></td><td><?=e($row['details'])?></td><td><?=e(format_datetime($row['action_at']))?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section></main><?php include 'includes/footer.php';?>
